<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Xander Zombie — Reel</title><style>*{box-sizing:border-box}body{margin:0;background:#111;color:#111;font-family:Arial,Helvetica,sans-serif}.top{position:sticky;top:0;z-index:5;background:#111;color:#eee;padding:12px 16px;border-bottom:5px solid #eee;display:flex;justify-content:space-between;gap:10px;align-items:center}.top b{letter-spacing:.12em}.top a{color:#111;background:#e8ddc2;border:3px solid #000;padding:7px 10px;text-decoration:none;font-weight:900}.feed{width:min(680px,100%);margin:auto;background:#d9d0b9;min-height:100vh;padding:18px}.episode{margin:20px 0 50px}.episode>h1{font-size:clamp(34px,10vw,68px);line-height:.9;margin:12px 0}.episode>p{font:18px/1.5 Georgia}.art{width:100%;border:7px solid #111;display:block;background:#111}.panel{border:7px solid #111;background:#f0e5c7;padding:18px;margin:15px 0;box-shadow:7px 7px 0 #111}.panel .n{font-weight:900;font-size:12px;letter-spacing:.15em}.panel h2{font:900 28px/1 Arial;margin:10px 0}.panel blockquote{font:900 20px Arial;margin:15px 0;background:#fff;border:4px solid #111;border-radius:40%;padding:18px}.empty{padding:50px 20px;text-align:center}</style></head><body><header class="top"><b>XANDER ZOMBIE // REEL MODE</b><a href="./">COMIC VIEW</a></header><main class="feed" id="feed"><div class="empty">Loading the dead kid…</div></main><script>const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));fetch('comic-api.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'public_list'})}).then(r=>r.json()).then(j=>{const items=j.items||[];document.querySelector('#feed').innerHTML=items.length?items.map(e=>`<article class="episode"><small>ISSUE ${String(e.issue).padStart(2,'0')}</small><h1>${esc(e.title)}</h1><p>${esc(e.summary)}</p>${e.art_url?`<img class="art" src="${esc(e.art_url)}" alt="${esc(e.title)}">`:''}${(e.panels||[]).map((p,i)=>`<section class="panel"><span class="n">PANEL ${i+1}</span><h2>${esc(p.caption)}</h2><p>${esc(p.visual)}</p>${p.dialogue?`<blockquote>${esc(p.dialogue)}</blockquote>`:''}</section>`).join('')}</article>`).join(''):'<div class="empty"><h1>Issue 01 lives in comic view.</h1><p>Studio-published strips will stack here vertically.</p></div>'}).catch(()=>document.querySelector('#feed').innerHTML='<div class="empty">The reel machine is unplugged.</div>')</script></body></html>